INSERT INTO team_members
  (id, slug, name, role, specialty, accent, short_bio, biography, expanded_bio, approach,
   collaboration, photo, location, email, github_url, linkedin_url, portfolio_url,
   skills, skill_groups, featured_project_slugs, achievements, interests, strengths, sort_order)
VALUES ('m2', 'aarav', 'Aarav', 'Backend & Database Developer', 'Spring Boot services, MySQL schemas and query plans', '#06D6A0',
  'I design the Java services and MySQL schemas the rest of the team builds against, and I care what happens on row one million.', 'Aarav owns the server side of the crew''s work: Spring Boot services, security configuration, migrations and the query plans nobody else wants to read. He is the one who adds the index before the demo, and the one who can explain why the endpoint is slow.', 'Backend work is mostly restraint. The tempting abstraction is usually the wrong one; the boring join table is usually the right one. I spend my time on the parts users never see: connection pools, transaction boundaries, migrations that can be rolled back, and logs that are specific enough to debug from.', 'Model the data first, protect it with validation at the boundary, and only add caching once something is measurably slow.',
  'I publish the contract — schema, endpoints, error shapes — before implementation so the frontend is never blocked waiting on me.', '/images/avatars/aarav.svg', 'Chennai, India', 'aarav@fullstackcrew.example', NULL,
  NULL, NULL,
  '["Java","Spring Boot","Spring Security","MySQL","Redis","JUnit","Docker","Maven","Linux"]', '{"frontend":["HTML","CSS","JavaScript"],"backend":["Java","Spring Boot","Spring Security","REST APIs","Node.js"],"database":["MySQL","MongoDB","Redis"],"tools":["Git","Maven","Docker","Linux","Postman"]}', '["shard-api","migrate-mono","pulseboard"]', '["Cut a report query from 11 seconds to under 200 milliseconds by restructuring the schema and adding a covering index.","Designed the multi-tenant isolation model used by the team''s API gateway.","Wrote the migration tooling the crew now uses for every schema change."]',
  '["Query optimisation","Distributed systems","Security modelling","Observability"]', '["Modelling data so constraints live in the schema, not in comments","Reading execution plans and fixing the actual bottleneck","Writing migrations that survive a rollback"]', 1)
