INSERT INTO team_members
  (id, slug, name, role, specialty, accent, short_bio, biography, expanded_bio, approach,
   collaboration, photo, location, email, github_url, linkedin_url, portfolio_url,
   skills, skill_groups, featured_project_slugs, achievements, interests, strengths, sort_order)
VALUES ('m3', 'sanjay', 'Sanjay', 'Frontend Developer · UI/UX', 'Interaction design, animation systems and accessible React', '#FF6B35',
  'I build the interfaces: motion, layout and interaction detail that make our products feel deliberate instead of assembled.', 'Sanjay owns the browser side of the crew. He builds the design tokens, the component library and the animation layer, then argues for the keyboard shortcut nobody asked for. His reviews are mostly about spacing, focus states and whether something responds in under 200 milliseconds.', 'A frontend is finished when it behaves well on a three-year-old phone with one thumb, not when it matches the mockup. I treat motion as feedback: it should explain what just happened and then get out of the way. Everything I build has a keyboard path and a reduced-motion fallback before it has a hover effect.', 'Build the real component with the ugliest data first, then style it, then animate it — never the other way round.',
  'I hand over components with the states already drawn — loading, empty, error — so nobody invents them downstream.', '/images/avatars/sanjay.svg', 'Hyderabad, India', 'sanjay@fullstackcrew.example', NULL,
  NULL, NULL,
  '["React","TypeScript","Tailwind CSS","Framer Motion","GSAP","Figma","WCAG","Vite"]', '{"frontend":["React","TypeScript","Tailwind CSS","HTML","CSS","JavaScript"],"backend":["Node.js","Express"],"database":["MongoDB"],"tools":["Figma","Git","GitHub","Vite","Chrome DevTools"]}', '["code-canvas","verdant-cart","pulseboard"]', '["Built the crew''s shared component library and the token set every project now starts from.","Took two dashboards to a clean Lighthouse accessibility pass, including full keyboard-only flows.","Set up the team''s reduced-motion policy for scroll animation."]',
  '["Motion design","Design systems","Accessibility","Rendering performance"]', '["Composing layouts that hold up from 320px to 1920px","Animation that communicates state instead of decorating it","Turning a Figma file into reusable tokens and components"]', 2)
