INSERT INTO projects
  (slug, title, description, thumbnail, technologies, categories, contributor_ids,
   live_demo_url, github_url, featured, year, overview, problem, solution, key_features,
   contributions, screenshots, sort_order)
VALUES ('pulseboard', 'PulseBoard', 'A real-time operations dashboard that streams service health into a single view, with alert rules your team can actually read six months later.', '/images/projects/pulseboard.svg',
  '["React","TypeScript","Spring Boot","MySQL","Redis","WebSockets","Tailwind CSS"]', '["Real-Time Applications","Full-Stack Applications"]', '["m1","m2","m3"]',
  NULL, NULL, 1, '2026',
  'PulseBoard aggregates service metrics, deploy events and error bursts into one live board. Operators choose what counts as a problem; the system holds that definition in versioned rules instead of tribal knowledge.', 'The teams we built this for were watching four tabs and a chat channel at the same time. When something broke, the incident narrative was reconstructed from scrollback, and the same failure reappeared a month later because nobody had written down the fix.', 'One WebSocket stream fans out normalised events; the client keeps a bounded ring buffer so memory stays flat over an eight-hour shift. Alert rules are declarative JSON stored against the project, validated on write, and rendered as plain English in the UI so a non-author can read them.',
  '["Live event stream with a bounded client buffer and automatic resync on reconnect","Declarative alert rules, version-controlled and rendered as human-readable sentences","Incident timeline stitched from deploys, errors and rule triggers","Keyboard-first navigation for every panel, including screen-reader announcements of new alerts"]', '[{"memberId":"m1","note":"Owned the event schema and the WebSocket contract between service and client."},{"memberId":"m2","note":"Designed the MySQL event store, retention job and Redis hot-path cache."},{"memberId":"m3","note":"Built the streaming UI, panel system and live-region announcement layer."}]', 'null',
  0)
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), thumbnail=VALUES(thumbnail),
  technologies=VALUES(technologies), categories=VALUES(categories),
  contributor_ids=VALUES(contributor_ids), live_demo_url=VALUES(live_demo_url),
  github_url=VALUES(github_url), featured=VALUES(featured), year=VALUES(year),
  overview=VALUES(overview), problem=VALUES(problem), solution=VALUES(solution),
  key_features=VALUES(key_features), contributions=VALUES(contributions),
  screenshots=VALUES(screenshots), sort_order=VALUES(sort_order);

INSERT INTO projects
  (slug, title, description, thumbnail, technologies, categories, contributor_ids,
   live_demo_url, github_url, featured, year, overview, problem, solution, key_features,
   contributions, screenshots, sort_order)
VALUES ('shard-api', 'ShardAPI', 'A multi-tenant REST gateway in Spring Boot: one deployment, strict per-tenant isolation, and rate limits you can reason about.', '/images/projects/shard-api.svg',
  '["Java","Spring Boot","Spring Security","MySQL","Redis","Docker","JUnit"]', '["Backend Systems","Developer Tools"]', '["m2","m1"]',
  NULL, NULL, 1, '2026',
  'ShardAPI fronts several customer databases behind one API surface. Requests carry a tenant identity, and the gateway routes, isolates, throttles and audits them without any consumer needing to know where the data physically lives.', 'Per-customer deployments were multiplying. Every bug fix had to be applied N times, and there was no honest answer to ''show me everything tenant B touched last week''.', 'Tenant resolution happens in a single filter that binds the identity to the request context, so downstream code cannot accidentally read another tenant. Connection pools are per-tenant and capped, and every access is written to an append-only audit stream.',
  '["Filter-level tenant binding so isolation cannot be bypassed by application code","Per-tenant connection pools with hard ceilings and backpressure","Token-bucket rate limiting backed by Redis","Append-only audit log queryable by tenant, actor and time range"]', '[{"memberId":"m2","note":"Built tenant resolution, pool isolation, rate limiting and the audit pipeline."},{"memberId":"m1","note":"Wrote the Spring Security model, integration tests and the rollout plan."}]', 'null',
  1)
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), thumbnail=VALUES(thumbnail),
  technologies=VALUES(technologies), categories=VALUES(categories),
  contributor_ids=VALUES(contributor_ids), live_demo_url=VALUES(live_demo_url),
  github_url=VALUES(github_url), featured=VALUES(featured), year=VALUES(year),
  overview=VALUES(overview), problem=VALUES(problem), solution=VALUES(solution),
  key_features=VALUES(key_features), contributions=VALUES(contributions),
  screenshots=VALUES(screenshots), sort_order=VALUES(sort_order);

INSERT INTO projects
  (slug, title, description, thumbnail, technologies, categories, contributor_ids,
   live_demo_url, github_url, featured, year, overview, problem, solution, key_features,
   contributions, screenshots, sort_order)
VALUES ('verdant-cart', 'VerdantCart', 'A plant-nursery storefront with an offline-tolerant cart, optimistic checkout and an admin panel small enough to learn in a day.', '/images/projects/verdant-cart.svg',
  '["React","TypeScript","Node.js","Express","MongoDB","Tailwind CSS"]', '["E-Commerce","Full-Stack Applications"]', '["m3","m1"]',
  NULL, NULL, 1, '2025',
  'VerdantCart sells live plants to a regional nursery. Stock changes hourly, availability is the whole product, and the owners needed to update it from a phone in a greenhouse rather than a desktop back office.', 'The old site sold plants that did not exist. Two staff edited one spreadsheet, customers discovered the truth at delivery, and refunds ate the margin on the popular items.', 'Availability is the customer-facing field, not a flag on a product record. The cart resolves stock on every navigation and degrades to a cached snapshot offline, then reconciles on reconnect. The admin is a single editable stock sheet sized for thumbs.',
  '["Stock-first data model with reservation on checkout start","Offline-tolerant cart with reconciliation when the connection returns","Optimistic UI with honest failure states — nothing claims success it did not get","One-screen admin inventory sheet usable on a 360px phone"]', '[{"memberId":"m3","note":"Designed the storefront flows, cart state machine and mobile admin sheet."},{"memberId":"m1","note":"Built the Express API, stock reservation logic and Mongo indexes."}]', 'null',
  2)
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), thumbnail=VALUES(thumbnail),
  technologies=VALUES(technologies), categories=VALUES(categories),
  contributor_ids=VALUES(contributor_ids), live_demo_url=VALUES(live_demo_url),
  github_url=VALUES(github_url), featured=VALUES(featured), year=VALUES(year),
  overview=VALUES(overview), problem=VALUES(problem), solution=VALUES(solution),
  key_features=VALUES(key_features), contributions=VALUES(contributions),
  screenshots=VALUES(screenshots), sort_order=VALUES(sort_order);

INSERT INTO projects
  (slug, title, description, thumbnail, technologies, categories, contributor_ids,
   live_demo_url, github_url, featured, year, overview, problem, solution, key_features,
   contributions, screenshots, sort_order)
VALUES ('code-canvas', 'CodeCanvas', 'Collaborative code scratchpad for pairing: shared cursors, per-file presence, and a session transcript you can keep after the call.', '/images/projects/code-canvas.svg',
  '["React","TypeScript","Node.js","WebSockets","MongoDB","Framer Motion"]', '["Productivity Tools","Frontend Projects","Real-Time Applications"]', '["m3","m2"]',
  NULL, NULL, 0, '2025',
  'CodeCanvas exists for the fifteen minutes at the start of a debugging session where two people need one scratchpad, not a repository. Open a link, paste the code, see each other''s cursors.', 'Screen-sharing is a bad medium for reasoning about code. The driver types and the observer watches, and the useful second pair of hands stays silent because there is no way in.', 'Presence is the product. Each participant gets a named cursor and a file-local selection, edits merge per-line so two people can work in the same file without fighting, and the transcript records who proposed what.',
  '["Per-file presence with named cursors and selections","Line-level merge so concurrent edits do not clobber each other","Session transcript export with attribution","Reduced-motion mode that still communicates presence through labels"]', '[{"memberId":"m3","note":"Built the editor surface, presence rendering and merge-conflict UX."},{"memberId":"m2","note":"Wrote the WebSocket relay, session persistence and transcript store."}]', 'null',
  3)
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), thumbnail=VALUES(thumbnail),
  technologies=VALUES(technologies), categories=VALUES(categories),
  contributor_ids=VALUES(contributor_ids), live_demo_url=VALUES(live_demo_url),
  github_url=VALUES(github_url), featured=VALUES(featured), year=VALUES(year),
  overview=VALUES(overview), problem=VALUES(problem), solution=VALUES(solution),
  key_features=VALUES(key_features), contributions=VALUES(contributions),
