INSERT INTO projects
  (slug, title, description, thumbnail, technologies, categories, contributor_ids,
   live_demo_url, github_url, featured, year, overview, problem, solution, key_features,
   contributions, screenshots, sort_order)
VALUES ('a11y-radar', 'A11yRadar', 'An in-browser accessibility auditor that reports keyboard-reachable problems in the order you will actually encounter them.', '/images/projects/a11y-radar.svg',
  '["TypeScript","React","Chrome Extension APIs","axe-core","Vite"]', '["Developer Tools","Frontend Projects"]', '["m1"]',
  NULL, NULL, 0, '2025',
  'A11yRadar walks the page the way a keyboard user does and reports what it could not reach, what it could not name, and what moved without warning. Findings are ordered by tab order rather than severity score.', 'Existing audit tools return a 200-item list sorted by rule name. Teams triage by count, fix the easy ones for the score, and the page stays unusable for the person who was never in the room.', 'The extension simulates a tab traversal and reports each stop: focus visible, label computed, role announced. Failures appear in traversal order with the exact key sequence that reached them, so the fix is a concrete reproduction rather than an abstract rule.',
  '["Tab-order traversal with per-stop focus and label assertions","Findings ordered by traversal position, not rule severity","Reproduction hint for every failure — the exact keys pressed to reach it","Diff view between two scans so regressions in a PR are visible"]', '[{"memberId":"m1","note":"Designed the traversal model and built the extension, rules engine and diff view."}]', 'null',
  4)
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), thumbnail=VALUES(thumbnail),
  technologies=VALUES(technologies), categories=VALUES(categories),
  contributor_ids=VALUES(contributor_ids), live_demo_url=VALUES(live_demo_url),
  github_url=VALUES(github_url), featured=VALUES(featured), year=VALUES(year),
  overview=VALUES(overview), problem=VALUES(problem), solution=VALUES(solution),
  key_features=VALUES(key_features), contributions=VALUES(contributions),
  screenshots=VALUES(screenshots), sort_order=VALUES(sort_order);

INSERT INTO projects
  (slug, title, description, thumbnail, technologies, categories, contributor_ids,
   live_demo_url, github_url, featured, year, overview, problem, solution, key_features,
   contributions, screenshots, sort_order)
VALUES ('migrate-mono', 'MigrateMono', 'A schema-migration CLI for MySQL projects that refuses to run anything it cannot undo.', '/images/projects/migrate-mono.svg',
  '["Java","MySQL","Maven","JUnit","Linux"]', '["Developer Tools","Backend Systems"]', '["m2"]',
  NULL, NULL, 0, '2024',
  'MigrateMono applies versioned SQL migrations with a hard rule: every up script must ship with a down script or a declared, reviewed exception. The tool prints a plan before it touches the database.', 'Our own projects lost staging databases to hand-run SQL. Migrations lived in a notes file, applied order depended on who ran them first, and rollback was an apology.', 'Migrations are numbered files with paired reversals, checksummed so drift is detected before deploy. A dry-run prints the exact statement sequence and estimated locks; applying requires an explicit target environment name.',
  '["Paired up/down scripts enforced at the file-layout level","Drift detection by checksum against the applied history table","Dry-run plan output with lock estimates before anything executes","Environment name must be typed, so staging never gets ''the prod migration''"]', '[{"memberId":"m2","note":"Built the CLI, checksum drift detection and the reversal enforcement rules."}]', 'null',
  5)
ON DUPLICATE KEY UPDATE
  title=VALUES(title), description=VALUES(description), thumbnail=VALUES(thumbnail),
  technologies=VALUES(technologies), categories=VALUES(categories),
