INSERT INTO site_content (content_key, payload)
VALUES ('brand', '{"name":"FullStack Crew","tagline":"WE DESIGN. WE BUILD. WE SHIP.","altTagline":"Different Minds. One Stack. Infinite Possibilities.","description":"We are a team of full-stack developers transforming ideas into powerful, responsive, and scalable digital experiences.","email":"hello@fullstackcrew.example","location":"Bengaluru, India"}')
ON DUPLICATE KEY UPDATE payload=VALUES(payload);
INSERT INTO site_content (content_key, payload)
VALUES ('navItems', '[{"label":"Home","to":"/","accent":"#4361EE"},{"label":"Team","to":"/team","accent":"#06D6A0"},{"label":"Projects","to":"/projects","accent":"#FF6B35"},{"label":"Skills","to":"/skills","accent":"#845EC2"},{"label":"Achievements","to":"/achievements","accent":"#FFD166"},{"label":"Contact","to":"/contact","accent":"#FF5A7A"}]')
