INSERT INTO site_content (content_key, payload)
VALUES ('coreValues', '[{"title":"Ship, then polish","body":"Every sprint ends with something a human can click. Refactors follow evidence, not guesswork.","accent":"#4361EE"},{"title":"Own the whole stack","body":"The person who draws the screen is comfortable writing the migration behind it.","accent":"#06D6A0"},{"title":"Accessible by default","body":"Keyboard paths, contrast and reduced motion are part of the definition of done, not a cleanup pass.","accent":"#FF6B35"},{"title":"Review generously","body":"Pull requests are conversations. We explain the why, and we change our minds on evidence.","accent":"#845EC2"}]')
ON DUPLICATE KEY UPDATE payload=VALUES(payload);
INSERT INTO site_content (content_key, payload)
VALUES ('workflow', '[{"step":"01","title":"Frame","body":"We turn the request into a one-page brief: who uses it, what changes, how we measure it.","accent":"#4361EE"},{"step":"02","title":"Design","body":"Flows before pixels. Components are chosen from a shared token set so screens stay consistent.","accent":"#FF5A7A"},{"step":"03","title":"Build","body":"Typed contracts between client and API, feature branches, small diffs, CI on every push.","accent":"#06D6A0"},{"step":"04","title":"Harden","body":"Unit and end-to-end checks, responsive sweeps at 320–1920px, keyboard-only walkthroughs.","accent":"#845EC2"},{"step":"05","title":"Ship & watch","body":"Deploy, then read logs and analytics for a week. Fix what the data says, not what we assumed.","accent":"#FF6B35"}]')
ON DUPLICATE KEY UPDATE payload=VALUES(payload);
